-- ============================================================
-- UniPak Database — Pakistan University Admissions Platform
-- Refined & normalized schema generated from source draft
-- ============================================================

DROP DATABASE IF EXISTS UniPak;
GO
CREATE DATABASE UniPak;
GO
USE UniPak;
GO

-- ---------------- Cities ----------------
CREATE TABLE Cities (
    CityID INT IDENTITY(1,1) PRIMARY KEY,
    CityName VARCHAR(100) NOT NULL UNIQUE
);

-- ---------------- Universities ----------------
CREATE TABLE Universities (
    UniversityID   INT PRIMARY KEY,
    CityID         INT NOT NULL,
    UniversityName VARCHAR(255) NOT NULL,
    Sector VARCHAR(20) NOT NULL default 'public',
    CHECK (Sector IN ('Public','Private')), 
    CONSTRAINT fk_universities_city FOREIGN KEY (CityID) REFERENCES Cities(CityID)
);
CREATE INDEX idx_universities_city ON Universities(CityID);

-- ---------------- Faculties / Schools ----------------
-- (SourceNotes column removed; ProgramsOffered normalized into the Programs table below)
CREATE TABLE Faculties (
    FacultyID       INT PRIMARY KEY,
    UniversityID    INT NOT NULL,
    FacultyName     VARCHAR(255) NOT NULL,
    Duration        VARCHAR(50),
    Semesters       INT,
    SemesterFee NVARCHAR(MAX),
    SourceNotes NVARCHAR(MAX),
    TestTotalMarksText NVARCHAR(MAX),
    NegativeMarking NVARCHAR(MAX),
    AlternativeTests NVARCHAR(MAX),
    TestSubjectsBreakdown NVARCHAR(MAX),
    TestFormat NVARCHAR(MAX),
    EntryTestSourceNotes NVARCHAR(MAX),
    HostelStatus varchar(50) not null default 'unspecified',
    check (HostelStatus in ('Yes','No','Limited','Unspecified')),
    HostelNote NVARCHAR(MAX),
    ApplicationMethod NVARCHAR(MAX),
    AggregateFormula NVARCHAR(MAX),
    CONSTRAINT fk_faculties_university FOREIGN KEY (UniversityID) REFERENCES Universities(UniversityID)
);
CREATE INDEX idx_faculties_university ON Faculties(UniversityID);

-- ---------------- Programs / Majors (one row per program, enables major-based filtering) ----------------
CREATE TABLE Programs (
    ProgramID      INT PRIMARY KEY,
    FacultyID      INT NOT NULL,
    ProgramName    VARCHAR(150) NOT NULL,
    MajorCategory  VARCHAR(100) NOT NULL,
    CONSTRAINT fk_programs_faculty FOREIGN KEY (FacultyID) REFERENCES Faculties(FacultyID)
);
CREATE INDEX idx_programs_faculty ON Programs(FacultyID);
CREATE INDEX idx_programs_major ON Programs(MajorCategory);

-- ============================================================
-- DATA
-- ============================================================

