-- ---------------- Admission tests ----------------
CREATE TABLE AdmissionTests (
    AdmissionTestID INT IDENTITY(1,1) PRIMARY KEY,
    FacultyID INT NOT NULL,
    TestName NVARCHAR(150) NOT NULL,
    TotalMarks DECIMAL(10,2) NULL,
    TotalMarksText NVARCHAR(MAX) NULL,
    IsPrimary BIT NOT NULL DEFAULT 0,
    SubjectBreakdown NVARCHAR(MAX) NULL,
    QuestionFormat NVARCHAR(MAX) NULL,
    NegativeMarking NVARCHAR(MAX) NULL,
    Notes NVARCHAR(MAX) NULL,
    CONSTRAINT fk_admissiontests_faculty FOREIGN KEY (FacultyID) REFERENCES Faculties(FacultyID),
    CONSTRAINT uq_admissiontests_faculty_name UNIQUE (FacultyID, TestName)
);
CREATE INDEX idx_admissiontests_faculty ON AdmissionTests(FacultyID);

-- ---------------- Programs ----------------

-- ============================================================
-- Helper view for the website: one row per program, with
-- university/city/faculty context flattened for easy filtering
-- ============================================================
CREATE VIEW ProgramSearchView AS
SELECT
    p.ProgramID,
    p.ProgramName,
    p.MajorCategory,
    f.FacultyID,
    f.FacultyName,
    f.Duration,
    f.Semesters,
    f.SemesterFee,
    f.HostelStatus,
    f.HostelNote,
    f.ApplicationMethod,
    f.AggregateFormula,
    u.UniversityID,
    u.UniversityName,
    u.Sector,
    c.CityID,
    c.CityName
FROM Programs p
JOIN Faculties f ON p.FacultyID = f.FacultyID
JOIN Universities u ON f.UniversityID = u.UniversityID
JOIN Cities c ON u.CityID = c.CityID;

-- ============================================================
-- University Merit Cut-offs
-- Imported from University_Merit_Cutoffs_2025(1).xlsx and
-- University_Merit_Cutoffs_2026(1).xlsx
--
-- UniversityID and ProgramID are nullable by design:
-- the source workbooks include universities/programs not yet
-- represented in the normalized base tables. Original names and
-- workbook coordinates are retained for complete traceability.
-- ============================================================

CREATE TABLE UniversityMeritCutoffs (
    MeritCutoffID       INT IDENTITY(1,1) PRIMARY KEY,
    UniversityID        INT NULL,
    ProgramID           INT NULL,
    CityID              INT NOT NULL,
    UniversityNameSource NVARCHAR(255) NOT NULL,
    ProgramNameSource    NVARCHAR(255) NOT NULL,
    AdmissionYear       SMALLINT NOT NULL,
    SessionName         NVARCHAR(50) NULL,
    CategoryTestBasis   NVARCHAR(300) NULL,
    ClosingMeritPercent DECIMAL(6,3) NULL,
    MeritListRound      NVARCHAR(100) NULL,
    MeritStatus         VARCHAR(20) NOT NULL,
    SourceReference     NVARCHAR(MAX) NULL,
    Notes               NVARCHAR(MAX) NULL,
    SourceWorkbook      NVARCHAR(260) NOT NULL,
    SourceSheet         NVARCHAR(100) NOT NULL,
    SourceRow           INT NOT NULL,
    ImportedAtUtc       DATETIME2(0) NOT NULL
                        CONSTRAINT df_meritcutoffs_importedatutc DEFAULT SYSUTCDATETIME(),

    CONSTRAINT fk_meritcutoffs_university
        FOREIGN KEY (UniversityID) REFERENCES Universities(UniversityID),
    CONSTRAINT fk_meritcutoffs_program
        FOREIGN KEY (ProgramID) REFERENCES Programs(ProgramID),
    CONSTRAINT fk_meritcutoffs_city
        FOREIGN KEY (CityID) REFERENCES Cities(CityID),
    CONSTRAINT ck_meritcutoffs_year
        CHECK (AdmissionYear BETWEEN 2000 AND 2100),
    CONSTRAINT ck_meritcutoffs_percentage
        CHECK (ClosingMeritPercent IS NULL OR
               (ClosingMeritPercent >= 0 AND ClosingMeritPercent <= 100)),
    CONSTRAINT ck_meritcutoffs_status
        CHECK (MeritStatus IN ('Reported','Estimated','Unavailable','Not Applicable')),
    CONSTRAINT uq_meritcutoffs_source
        UNIQUE (SourceWorkbook, SourceSheet, SourceRow)
);

CREATE INDEX idx_meritcutoffs_year
    ON UniversityMeritCutoffs(AdmissionYear);

CREATE INDEX idx_meritcutoffs_university_year
    ON UniversityMeritCutoffs(UniversityID, AdmissionYear);

CREATE INDEX idx_meritcutoffs_program_year
    ON UniversityMeritCutoffs(ProgramID, AdmissionYear);

